def transform(grid):
    h, w = len(grid), max(map(len, grid))
    out = [row[:] + [0] * (w - len(row)) for row in grid]
    rows = {r for r, row in enumerate(grid) if len(row) == w and row[0] == 1 and row[-1] == 1}
    cols = {c for c in range(w) if grid[0][c] == 1 and grid[-1][c] == 1}
    for r in rows:
        for c in range(w):
            out[r][c] = 1
    for c in cols:
        for r in range(h):
            out[r][c] = 1
    seen = set()
    for r in range(h):
        for c in range(len(grid[r])):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < len(grid[yy]) and grid[yy][xx] == 2 and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            if any(y in rows or x in cols for y, x in component):
                for y, x in component:
                    out[y][x] = 1
    return out

